rules.logic:
// Match native card link style
element.style.display = 'block';
element.style.textDecoration = 'none';
element.style.borderRadius = '8px';
element.style.cursor = 'pointer';
element.style.transition = 'box-shadow 0.15s ease';
element.style.outline = 'none';

// On hover, add shadow like native cards
element.onmouseenter = function() {
  element.style.boxShadow = '0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)';
};
element.onmouseleave = function() {
  element.style.boxShadow = 'none';
};

element.style.position = 'relative';
element.style.overflow = 'hidden';
element.style.borderRadius = '16px';
element.style.transition = 'box-shadow 0.15s ease';
element.style.aspectRatio = '1 / 1';

element.style.display = 'block';
element.style.width = '100%';
element.style.height = '100%';
element.style.backgroundSize = 'cover';
element.style.backgroundPosition = 'center';
element.style.borderRadius = '12px';
element.style.transform = 'scale(1.01)';
element.style.transition = 'transform 0.15s ease';

element.style.fontFamily = 'inherit';
element.style.fontSize = '14px';
element.style.fontWeight = '700';
element.style.lineHeight = '1.5';
element.style.letterSpacing = '-0.015em';
element.style.color = '#111827';
element.style.display = '-webkit-box';
element.style.webkitLineClamp = '2';
element.style.webkitBoxOrient = 'vertical';
element.style.overflow = 'hidden';
element.style.marginBottom = '4px';
element.style.paddingBottom = '2px';

element.style.fontSize = '11px';
element.style.fontWeight = '500';
element.style.color = '#6B7280';
element.style.display = 'flex';
element.style.alignItems = 'center';
element.style.gap = '4px';

// Keep the content but remove visual "sponsored" badges for unified look
if (element.classList.contains('trc-content-sponsored')) {
  element.style.overflow = 'visible';
} else {
  element.style.display = 'none';
}

element.style.display = 'flex';
element.style.flexDirection = 'column';
element.style.background = '#fff';
element.style.borderRadius = '0';
element.style.padding = '0';
element.style.gap = '0';

element.style.fontSize = '20px';
element.style.fontWeight = '700';
element.style.letterSpacing = '-0.015em';
element.style.lineHeight = '1.5';
element.style.color = '#111827';
element.style.paddingBottom = '16px';

// Only hide if it's truly empty (no child content)
if (!element.innerHTML.trim()) {
  element.style.display = 'none';
}

// Add hover effect to match native cards
element.style.overflow = 'hidden';

var holder = element;
holder.onmouseenter = function() {
  var img = this.querySelector('.thumbBlock');
  if (img) {
    img.style.transform = 'scale(1.05)';
  }
  this.style.boxShadow = '0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)';
};
holder.onmouseleave = function() {
  var img = this.querySelector('.thumbBlock');
  if (img) {
    img.style.transform = 'scale(1.01)';
  }
  this.style.boxShadow = 'none';
};

element.style.paddingTop = '24px';
element.style.paddingBottom = '16px';
element.style.marginBottom = '0';
element.style.borderBottom = 'none';
element.style.paddingLeft = '0';
element.style.paddingRight = '0';
